import {
  parseCsv,
  normalizeQuestionInput,
  validateQuestion,
  questionIngestionService
} from '../src/services/questionIngestionService.js';

async function runCompatibilityTest() {
  console.log('--- ExamSathi AI: Testing CSV Ingestion Pipeline Compatibility ---');

  // Sample CSV exactly as generated by tools/pdf_mcq_generator.py
  const sampleCsv = [
    'question_text,option_a,option_b,option_c,option_d,correct_option,correct_answer_text,difficulty,subject,subject_id,exam,exam_id,topic,syllabus_topic_id,explanation,source_title,source_page,source_url,question_origin,verification_status,is_published',
    '"Which normal form eliminates partial dependency on a composite primary key?","1NF (First Normal Form)","2NF (Second Normal Form)","3NF (Third Normal Form)","BCNF (Boyce-Codd Normal Form)",1,"2NF (Second Normal Form)",Moderate,"Computer Science",a1000000-0000-0000-0000-000000000007,fpsc-lecturer-cs-2026,e1000000-0000-0000-0000-000000000005,"Database Systems: Normalization, BCNF & ACID Transactions",d1000000-0000-0005-0000-000000000002,"2NF eliminates partial dependency on composite keys.",Lecturer_CS_Notes.pdf,Pages 3-4,,ai_generated_practice,practice_exercise,false'
  ].join('\n');

  console.log('[1] Parsing CSV with project RFC 4180 parser...');
  const parsedRows = parseCsv(sampleCsv);
  if (parsedRows.length !== 1) {
    throw new Error(`Expected 1 parsed row, got ${parsedRows.length}`);
  }
  console.log(' -> Successfully parsed 1 row.');

  console.log('[2] Normalizing with normalizeQuestionInput...');
  const normalized = normalizeQuestionInput(parsedRows[0]);
  if (normalized.options.length !== 4) {
    throw new Error(`Expected 4 options, got ${normalized.options.length}`);
  }
  if (normalized.correct_option !== 1) {
    throw new Error(`Expected correct_option 1, got ${normalized.correct_option}`);
  }
  if (normalized.is_published !== false) {
    throw new Error(`Expected is_published to be false for draft safety, got ${normalized.is_published}`);
  }
  console.log(' -> Canonical structure verified: 4 options, 0-based answer key, draft unpublished status.');

  console.log('[3] Validating against database reference context...');
  const context = await questionIngestionService.getReferenceContext();
  const valResult = validateQuestion(normalized, context);
  if (!valResult.valid) {
    throw new Error(`Validation failed: ${JSON.stringify(valResult.errors)}`);
  }
  console.log(' -> Foreign key IDs verified against live Supabase reference context.');
  console.log(`    Resolved Subject ID: ${valResult.resolved.subject_id}`);
  console.log(`    Resolved Exam ID: ${valResult.resolved.exam_id}`);
  console.log(`    Resolved Topic ID: ${valResult.resolved.syllabus_topic_id}`);

  console.log('[4] Ingesting in dry-run mode via questionIngestionService...');
  const ingestReport = await questionIngestionService.ingestQuestions(sampleCsv, { dryRun: true });
  if (!ingestReport.success || ingestReport.validCount !== 1) {
    throw new Error(`Ingest dry run failed: ${JSON.stringify(ingestReport)}`);
  }
  console.log(' -> Ingestion dry-run succeeded without errors.');

  console.log('\n========================================================================');
  console.log('>>> VERIFICATION PASSED: Exported CSV is 100% compatible with Supabase! <<<');
  console.log('========================================================================\n');
}

runCompatibilityTest().catch(err => {
  console.error('[FAILED]', err);
  process.exit(1);
});
